package imagesearch

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

// verdictOf runs HubSearcher against endpoint and classifies the answer.
func verdictOf(ctx context.Context, endpoint string) (Outcome, error) {
	imgs, partial, err := HubSearcher{Endpoint: endpoint}.Search(ctx, Target{}, Query{Text: "nginx"})
	return Classify(err, len(imgs), partial), err
}

func TestVerdictHTTP(t *testing.T) {
	cases := []struct {
		name   string
		status int
		body   string
		want   Verdict
	}{
		{"404", http.StatusNotFound, "", VerdictRefused},
		{"405", http.StatusMethodNotAllowed, "", VerdictRefused},
		"wrapped 403": fmt.Errorf("hub search: %w", &oci.StatusError{Code: 403, Source: oci.SourceRegistry}),
	}
	for name, cause := range errs {
		t.Run(name, func(t *testing.T) {
			withImageSearcher(t, &fakeSearcher{})
			logs := captureLog(t)

			m := searchLot(t, threeRegistryModel(t))
			m = answerFor(t, m, "hub", oneImage("alpha"), false, nil)
			m = answerFor(t, m, "prod", nil, false, cause)

